/* {{name}} — created by `arc1 new`. A ship moves right and wraps around;
 * RIGHT doubles its speed. See docs/API.md for the arc1/game.h contract. */
#include <arc1/game.h>

#include "arc1_assets.h" /* generated by `arc1 build` from assets/ */

int arc1_main(void) {
    if (arc1_init() != ARC1_OK) return 1;

    arc1_sprite ship;
    if (arc1_sprite_create(ARC1_ASSET_SHIP, ARC1_ASSET_SHIP_W,
                           ARC1_ASSET_SHIP_H, &ship) != ARC1_OK)
        return 2;

    int x = 0;
    while (arc1_running()) {
        arc1_input_poll();
        x += (arc1_input_held(0) & ARC1_BTN_RIGHT) ? 2 : 1;
        if (x >= ARC1_SCREEN_W) x = -ARC1_ASSET_SHIP_W;

        if (arc1_frame_begin(1) != ARC1_OK) return 3;
        arc1_sprite_draw(ship, x, (ARC1_SCREEN_H - ARC1_ASSET_SHIP_H) / 2);
        arc1_frame_end();
    }
    return 0;
}
